"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { Check, ChevronDown, CircleDashed, CircleUserRound } from "lucide-react";

type DivProps = React.ComponentProps<"div">;

export type StatusOptionColor = "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5" | "muted" | "destructive";
export type StatusDropdownSelectKind = "dot" | "icon" | "avatar";

export type StatusOption = {
  value: string;
  label: string;
  /** Colors the dot; once the dot has landed the trigger pill is tinted with the same color. */
  color?: StatusOptionColor;
  /** Drawn instead of the dot when kind is "icon"; for kind "avatar" it is the fallback when there is no photo. */
  icon?: React.ReactNode;
  avatarUrl?: string;
  /** Options with the same group are listed under a small heading. */
  group?: string;
  /** Single key that picks this option while the list is open; shown at the right edge of the row. */
  shortcut?: string;
  disabled?: boolean;
};

export type StatusDropdownSelectProps = DivProps & {
  options: StatusOption[];
  value?: string | null;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  kind?: StatusDropdownSelectKind;
  placeholder?: string;
  /** Accessible name of the field, for example "Status". */
  label?: string;
  size?: "sm" | "md";
  /** When false the chosen marker swaps in place instead of flying from the list to the trigger. */
  fly?: boolean;
  align?: "start" | "end";
  disabled?: boolean;
  /** Renders a hidden input so the select can take part in a form. */
  name?: string;
  menuWidth?: number;
};

type MenuState = null | "open" | "closing";
type Flight = { value: string; from: Box; to: Box; scale: number; token: number };
type Box = { left: number; top: number; width: number; height: number };

const FLY_MS = 420;
const MENU_OPEN_MS = 160;
const MENU_CLOSE_MS = 120;
const MENU_CLOSE_FLYING_MS = 240;
const ROLL_MS = 220;
const TYPEAHEAD_MS = 600;
const GAP = 6;
const EDGE = 8;
const EASE_FLY = "cubic-bezier(0.55, 0, 0.25, 1)";
const EASE_OUT = "cubic-bezier(0.22, 1, 0.36, 1)";

const COLOR_VAR = {
  "chart-1": "var(--color-chart-1)",
  "chart-2": "var(--color-chart-2)",
  "chart-3": "var(--color-chart-3)",
  "chart-4": "var(--color-chart-4)",
  "chart-5": "var(--color-chart-5)",
  muted: "var(--color-muted-foreground)",
  destructive: "var(--color-destructive)",
} as const;

const SIZE = {
  md: { trigger: "h-8 gap-1.5 pl-2 pr-1.5 text-[13px]", slot: "size-[18px]", label: "h-[18px] leading-[18px]", avatar: 18, chevron: "size-3.5" },
  sm: { trigger: "h-7 gap-1 pl-1.5 pr-1 text-xs", slot: "size-4", label: "h-4 leading-4", avatar: 16, chevron: "size-3" },
} as const;

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

function animatable(node: Element | null, reduced: boolean): node is HTMLElement {
  return !!node && !reduced && typeof (node as HTMLElement).animate === "function";
}

const box = (rect: DOMRect): Box => ({ left: rect.left, top: rect.top, width: rect.width, height: rect.height });

function dotColor(option: StatusOption) {
  if (option.color === "muted") return "color-mix(in oklab, var(--color-muted-foreground) 55%, transparent)";
  return option.color ? COLOR_VAR[option.color] : "var(--color-foreground)";
}

function Marker({ option, kind, avatarSize }: { option: StatusOption | null; kind: StatusDropdownSelectKind; avatarSize: number }) {
  if (!option) return <CircleDashed data-marker className="size-3.5 text-muted-foreground" strokeWidth={1.75} aria-hidden="true" />;
  if (kind === "avatar") {
    if (option.avatarUrl) {
      return (
        <img
          data-marker
          src={option.avatarUrl}
          alt=""
          width={avatarSize}
          height={avatarSize}
          draggable={false}
          className="shrink-0 rounded-full object-cover ring-1 ring-border"
          style={{ width: avatarSize, height: avatarSize }}
        />
      );
    }
    if (option.icon) return <span data-marker aria-hidden="true" className="flex items-center justify-center text-muted-foreground [&>svg]:size-3.5">{option.icon}</span>;
    return <CircleUserRound data-marker className="size-3.5 text-muted-foreground" strokeWidth={1.75} aria-hidden="true" />;
  }
  if (kind === "icon" && option.icon) {
    return (
      <span data-marker aria-hidden="true" className="flex items-center justify-center [&>svg]:size-3.5" style={option.color ? { color: COLOR_VAR[option.color] } : undefined}>
        {option.icon}
      </span>
    );
  }
  return <span data-marker aria-hidden="true" className="size-2 rounded-full" style={{ backgroundColor: dotColor(option) }} />;
}

function RollLabel({ text, order, reduced, id, className = "" }: { text: string; order: number; reduced: boolean; id: string; className?: string }) {
  const [state, setState] = React.useState({ text, leaving: null as string | null, up: true });
  const inRef = React.useRef(null as HTMLSpanElement | null);
  const outRef = React.useRef(null as HTMLSpanElement | null);
  const lastOrder = React.useRef(order);
  const timer = React.useRef(0);

  React.useLayoutEffect(() => {
    const up = order >= lastOrder.current;
    lastOrder.current = order;
    if (text === state.text) return;
    if (reduced) { setState({ text, leaving: null, up }); return; }
    setState({ text, leaving: state.text, up });
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setState((current) => ({ ...current, leaving: null })), ROLL_MS + 60);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, order]);

  React.useLayoutEffect(() => {
    if (state.leaving === null) return;
    const sign = state.up ? 1 : -1;
    if (animatable(inRef.current, reduced)) inRef.current.animate([{ transform: `translateY(${sign * 100}%)`, opacity: 0 }, { transform: "translateY(0)", opacity: 1 }], { duration: ROLL_MS, easing: EASE_OUT });
    if (animatable(outRef.current, reduced)) outRef.current.animate([{ transform: "translateY(0)", opacity: 1 }, { transform: `translateY(${-sign * 100}%)`, opacity: 0 }], { duration: ROLL_MS, easing: EASE_OUT, fill: "forwards" });
  }, [state.leaving, state.text, reduced]);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  return (
    <span id={id} data-label className={`relative grid min-w-0 overflow-hidden ${className}`}>
      <span ref={inRef} data-label-item className="col-start-1 row-start-1 truncate">{state.text}</span>
      {state.leaving !== null && <span ref={outRef} data-label-item aria-hidden="true" className="col-start-1 row-start-1 truncate">{state.leaving}</span>}
    </span>
  );
}

export function StatusDropdownSelect({
  options,
  value,
  defaultValue,
  onValueChange,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  kind = "dot",
  placeholder = "Select",
  label,
  size = "md",
  fly = true,
  align = "start",
  disabled = false,
  name,
  menuWidth = 224,
  className = "",
  ref,
  ...rest
}: StatusDropdownSelectProps) {
  const reduced = useReducedMotion();
  const baseId = React.useId();
  const triggerId = `${baseId}-trigger`;
  const listboxId = `${baseId}-listbox`;
  const labelId = `${baseId}-label`;
  const valueId = `${baseId}-value`;
  const dims = SIZE[size];

  const [localValue, setLocalValue] = React.useState(defaultValue ?? null);
  const selected = value === undefined ? localValue : value;
  const [localOpen, setLocalOpen] = React.useState(defaultOpen);
  const open = openProp === undefined ? localOpen : openProp;
  const [menuState, setMenuState] = React.useState(null as MenuState);
  const [highlighted, setHighlighted] = React.useState(null as string | null);
  const [shown, setShown] = React.useState(selected);
  const [flight, setFlight] = React.useState(null as Flight | null);
  const [announcement, setAnnouncement] = React.useState("");

  const rootRef = React.useRef(null as HTMLDivElement | null);
  const triggerRef = React.useRef(null as HTMLButtonElement | null);
  const slotRef = React.useRef(null as HTMLSpanElement | null);
  const menuRef = React.useRef(null as HTMLUListElement | null);
  const ghostRef = React.useRef(null as HTMLSpanElement | null);
  const handled = React.useRef(selected);
  const flightToken = React.useRef(0);
  const menuToken = React.useRef(0);
  const landed = React.useRef(false);
  const firstShown = React.useRef(true);
  const typeahead = React.useRef({ buffer: "", at: 0 });
  const openFocus = React.useRef("selected" as "selected" | "last");

  const enabled = options.filter((option) => !option.disabled);
  const indexOf = (optionValue: string | null) => options.findIndex((option) => option.value === optionValue);
  const shownOption = shown === null ? null : options.find((option) => option.value === shown) ?? null;
  const flightOption = flight ? options.find((option) => option.value === flight.value) ?? null : null;
  const tint = shownOption?.color ? COLOR_VAR[shownOption.color] : null;

  const setOpen = React.useCallback((next: boolean) => {
    if (openProp === undefined) setLocalOpen(next);
    onOpenChange?.(next);
  }, [openProp, onOpenChange]);

  const select = (next: string) => {
    const option = options.find((candidate) => candidate.value === next);
    if (!option || option.disabled) return;
    if (next !== selected) {
      if (value === undefined) setLocalValue(next);
      onValueChange?.(next);
    }
    setOpen(false);
    triggerRef.current?.focus({ preventScroll: true });
  };

  React.useLayoutEffect(() => {
    if (handled.current === selected) return;
    handled.current = selected;
    const menu = menuRef.current;
    const slot = slotRef.current;
    const row = menu && selected !== null ? [...menu.querySelectorAll("[data-option]")].find((node) => (node as HTMLElement).dataset.option === selected) : null;
    const marker = row?.querySelector("[data-marker]") ?? null;
    if (fly && !reduced && marker && slot) {
      const from = marker.getBoundingClientRect();
      const to = slot.getBoundingClientRect();
      if (from.width > 0 && to.width > 0) {
        flightToken.current += 1;
        setHighlighted(selected);
        setFlight({ value: selected as string, from: box(from), to: box(to), scale: kind === "avatar" ? dims.avatar / from.width : 1, token: flightToken.current });
        return;
      }
    }
    flightToken.current += 1;
    landed.current = false;
    setFlight(null);
    setShown(selected);
  }, [selected, fly, reduced, kind, dims.avatar]);

  React.useLayoutEffect(() => {
    if (!flight) return;
    const ghost = ghostRef.current;
    const token = flight.token;
    const land = () => {
      if (token !== flightToken.current) return;
      landed.current = true;
      setShown(flight.value);
      setFlight(null);
    };
    if (!animatable(ghost, reduced)) { land(); return; }
    const { from, to, scale } = flight;
    const dx = to.left + to.width / 2 - (from.left + from.width / 2);
    const dy = to.top + to.height / 2 - (from.top + from.height / 2);
    const lift = "drop-shadow(0 6px 8px color-mix(in oklab, var(--color-foreground) 28%, transparent))";
    const animation = ghost.animate(
      [
        { transform: "translate(0px, 0px) scale(1)", filter: "drop-shadow(0 0 0 transparent)" },
        { transform: `translate(${dx * 0.5}px, ${dy * 0.5 - 4}px) scale(${((1 + scale) / 2) * 1.25})`, filter: lift, offset: 0.5 },
        { transform: `translate(${dx}px, ${dy}px) scale(${scale})`, filter: "drop-shadow(0 0 0 transparent)" },
      ],
      { duration: FLY_MS, easing: EASE_FLY, fill: "forwards" },
    );
    animation.onfinish = land;
    return () => animation.cancel();
  }, [flight, reduced]);

  React.useLayoutEffect(() => {
    if (firstShown.current) { firstShown.current = false; return; }
    const slot = slotRef.current;
    if (landed.current && animatable(slot, reduced)) {
      slot.animate([{ transform: "scale(1.3)" }, { transform: "scale(1)" }], { duration: ROLL_MS, easing: EASE_OUT });
    }
    landed.current = false;
    if (shownOption) setAnnouncement(`${label ?? "Selected"}: ${shownOption.label}`);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [shown]);

  const place = React.useCallback(() => {
    const trigger = triggerRef.current;
    const menu = menuRef.current;
    if (!trigger || !menu) return;
    menu.style.maxHeight = "";
    menu.style.overflowY = "";
    const rect = trigger.getBoundingClientRect();
    const height = menu.offsetHeight;
    const width = menu.offsetWidth;
    const below = window.innerHeight - rect.bottom - GAP - EDGE;
    const above = rect.top - GAP - EDGE;
    const placement = height <= below || below >= above ? "bottom" : "top";
    const room = placement === "bottom" ? below : above;
    const finalHeight = Math.min(height, Math.max(96, room));
    if (finalHeight < height) { menu.style.maxHeight = `${finalHeight}px`; menu.style.overflowY = "auto"; }
    const top = placement === "bottom" ? rect.bottom + GAP : rect.top - GAP - finalHeight;
    const wanted = align === "end" ? rect.right - width : rect.left;
    const left = Math.min(Math.max(wanted, EDGE), Math.max(EDGE, window.innerWidth - EDGE - width));
    menu.style.top = `${top}px`;
    menu.style.left = `${left}px`;
    menu.style.transformOrigin = `${align === "end" ? "right" : "left"} ${placement === "bottom" ? "top" : "bottom"}`;
    menu.dataset.placement = placement;
  }, [align]);

  React.useLayoutEffect(() => {
    if (open) {
      if (!disabled) setMenuState("open");
      return;
    }
    setMenuState((current) => (current === "open" ? "closing" : current));
  }, [open, disabled]);

  React.useLayoutEffect(() => {
    const menu = menuRef.current;
    if (menuState === null || !menu) return;
    const token = ++menuToken.current;
    for (const running of menu.getAnimations()) running.cancel();
    if (menuState === "open") {
      place();
      const current = selected !== null && enabled.some((option) => option.value === selected) ? selected : null;
      const fallback = openFocus.current === "last" ? enabled[enabled.length - 1]?.value ?? null : enabled[0]?.value ?? null;
      setHighlighted(current ?? fallback);
      openFocus.current = "selected";
      menu.focus({ preventScroll: true });
      if (animatable(menu, reduced)) {
        menu.animate([{ opacity: 0, transform: "scale(0.96)" }, { opacity: 1, transform: "scale(1)" }], { duration: MENU_OPEN_MS, easing: EASE_OUT });
      }
      return;
    }
    const finish = () => { if (token === menuToken.current) setMenuState(null); };
    if (!animatable(menu, reduced)) { finish(); return; }
    const closing = menu.animate([{ opacity: 1, transform: "scale(1)" }, { opacity: 0, transform: "scale(0.98)" }], { duration: flight ? MENU_CLOSE_FLYING_MS : MENU_CLOSE_MS, easing: "ease-in", fill: "forwards" });
    closing.onfinish = finish;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [menuState]);

  React.useEffect(() => {
    if (menuState !== "open") return;
    const reposition = () => place();
    const onPointer = (event: PointerEvent) => {
      const target = event.target;
      if (!(target instanceof Node)) return;
      if (rootRef.current?.contains(target) || menuRef.current?.contains(target)) return;
      setOpen(false);
    };
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      setOpen(false);
      triggerRef.current?.focus({ preventScroll: true });
    };
    window.addEventListener("resize", reposition);
    window.addEventListener("scroll", reposition, true);
    document.addEventListener("pointerdown", onPointer);
    document.addEventListener("keydown", onKey);
    return () => {
      window.removeEventListener("resize", reposition);
      window.removeEventListener("scroll", reposition, true);
      document.removeEventListener("pointerdown", onPointer);
      document.removeEventListener("keydown", onKey);
    };
  }, [menuState, place, setOpen]);

  React.useEffect(() => {
    if (menuState !== "open" || highlighted === null) return;
    const row = [...(menuRef.current?.querySelectorAll("[data-option]") ?? [])].find((node) => (node as HTMLElement).dataset.option === highlighted);
    if (row instanceof HTMLElement && menuRef.current && menuRef.current.scrollHeight > menuRef.current.clientHeight) row.scrollIntoView({ block: "nearest" });
  }, [highlighted, menuState]);

  const move = (step: number, edge?: "first" | "last") => {
    if (!enabled.length) return;
    const current = enabled.findIndex((option) => option.value === highlighted);
    let next = edge === "first" ? 0 : edge === "last" ? enabled.length - 1 : current < 0 ? (step > 0 ? 0 : enabled.length - 1) : current + step;
    next = Math.min(enabled.length - 1, Math.max(0, next));
    setHighlighted(enabled[next]?.value ?? null);
  };

  const typeTo = (char: string) => {
    const now = performance.now();
    const state = typeahead.current;
    state.buffer = now - state.at > TYPEAHEAD_MS ? char : state.buffer + char;
    state.at = now;
    const repeated = state.buffer.length > 1 && [...state.buffer].every((letter) => letter === state.buffer.charAt(0));
    const needle = (repeated ? state.buffer.charAt(0) : state.buffer).toLowerCase();
    const start = enabled.findIndex((option) => option.value === highlighted);
    const offset = repeated || state.buffer.length === 1 ? 1 : 0;
    for (let index = 0; index < enabled.length; index += 1) {
      const option = enabled[(Math.max(start, 0) + offset + index) % enabled.length];
      if (option && option.label.toLowerCase().startsWith(needle)) { setHighlighted(option.value); return; }
    }
  };

  const onTriggerKeyDown = (event: React.KeyboardEvent) => {
    if (disabled) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp" || event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      openFocus.current = event.key === "ArrowUp" ? "last" : "selected";
      setOpen(true);
    }
  };

  const onListKeyDown = (event: React.KeyboardEvent) => {
    const key = event.key;
    if (key === "ArrowDown") { event.preventDefault(); move(1); return; }
    if (key === "ArrowUp") { event.preventDefault(); move(-1); return; }
    if (key === "Home") { event.preventDefault(); move(0, "first"); return; }
    if (key === "End") { event.preventDefault(); move(0, "last"); return; }
    if (key === "Tab") { event.preventDefault(); setOpen(false); triggerRef.current?.focus({ preventScroll: true }); return; }
    if (key === "Enter" || (key === " " && typeahead.current.buffer === "")) {
      event.preventDefault();
      if (highlighted !== null) select(highlighted);
      return;
    }
    if (key.length !== 1 || event.altKey || event.ctrlKey || event.metaKey) return;
    event.preventDefault();
    const shortcut = enabled.find((option) => option.shortcut !== undefined && option.shortcut.toLowerCase() === key.toLowerCase());
    if (shortcut) { select(shortcut.value); return; }
    if (key.trim() !== "" || typeahead.current.buffer !== "") typeTo(key);
  };

  const groups: { name: string | null; options: StatusOption[] }[] = [];
  for (const option of options) {
    const name = option.group ?? null;
    const last = groups[groups.length - 1];
    if (last && last.name === name) last.options.push(option);
    else groups.push({ name, options: [option] });
  }

  const shownLabel = shownOption?.label ?? placeholder;
  const tinted = tint !== null;

  return (
    <div
      {...rest}
      ref={(node) => { rootRef.current = node; if (typeof ref === "function") ref(node); else if (ref) (ref as { current: HTMLDivElement | null }).current = node; }}
      data-slot="status-dropdown-select"
      data-kind={kind}
      data-size={size}
      data-state={open ? "open" : "closed"}
      data-value={selected ?? ""}
      data-shown={shown ?? ""}
      data-flying={flight ? "true" : "false"}
      className={`relative inline-flex max-w-full ${className}`}
    >
      {label && <span id={labelId} className="sr-only">{label}</span>}
      {name && <input type="hidden" name={name} value={selected ?? ""} />}
      <button
        ref={triggerRef}
        id={triggerId}
        type="button"
        role="combobox"
        data-trigger
        data-tinted={tinted ? "true" : "false"}
        data-placeholder={shownOption ? undefined : "true"}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={menuState !== null ? listboxId : undefined}
        aria-labelledby={label ? `${labelId} ${valueId}` : valueId}
        disabled={disabled}
        onClick={() => { if (!disabled) setOpen(!open); }}
        onKeyDown={onTriggerKeyDown}
        className={`relative inline-flex max-w-full items-center rounded-full bg-background font-medium text-foreground outline-none ring-1 ring-border transition-[background-color,box-shadow,color,filter] duration-200 ease-out [--sds-mix:14%] dark:[--sds-mix:26%] hover:brightness-[0.97] dark:hover:brightness-[1.12] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none data-[state=open]:brightness-[0.97] dark:data-[state=open]:brightness-[1.12] ${dims.trigger}`}
        data-state={open ? "open" : "closed"}
        style={{
          "--sds-color": tint ?? "var(--color-border)",
          backgroundColor: tinted ? "color-mix(in oklab, var(--sds-color) var(--sds-mix), var(--color-background))" : undefined,
          "--tw-ring-color": tinted ? "color-mix(in oklab, var(--sds-color) 38%, var(--color-border))" : undefined,
        } as React.CSSProperties}
      >
        <span ref={slotRef} data-trigger-slot aria-hidden="true" className={`relative flex shrink-0 items-center justify-center ${dims.slot}`}>
          <Marker option={shownOption} kind={kind} avatarSize={dims.avatar} />
        </span>
        <RollLabel id={valueId} text={shownLabel} order={indexOf(shown)} reduced={reduced} className={`${dims.label} ${shownOption ? "" : "text-muted-foreground"}`} />
        <ChevronDown aria-hidden="true" className={`${dims.chevron} shrink-0 text-muted-foreground`} />
      </button>
      <span role="status" aria-live="polite" data-announce className="sr-only">{announcement}</span>
      {menuState !== null && createPortal(
        <ul
          ref={menuRef}
          id={listboxId}
          role="listbox"
          tabIndex={-1}
          aria-labelledby={label ? labelId : triggerId}
          aria-activedescendant={highlighted !== null && menuState === "open" ? `${baseId}-opt-${indexOf(highlighted)}` : undefined}
          data-menu
          data-state={menuState}
          onKeyDown={onListKeyDown}
          className="fixed left-0 top-0 z-50 m-0 list-none rounded-xl bg-popover p-1 text-popover-foreground shadow-lg shadow-foreground/10 ring-1 ring-border outline-none will-change-[transform,opacity]"
          style={{ width: menuWidth }}
        >
          {groups.map((group, groupIndex) => (
            <React.Fragment key={group.name ?? `group-${groupIndex}`}>
              {group.name !== null && (
                <li role="presentation" data-group className={`px-2 pb-1 text-[11px] font-medium text-muted-foreground ${groupIndex === 0 ? "pt-1" : "pt-2"}`}>
                  {group.name}
                </li>
              )}
              {group.options.map((option) => {
                const index = indexOf(option.value);
                const isSelected = option.value === selected;
                const isHighlighted = option.value === highlighted;
                return (
                  <li
                    key={option.value}
                    id={`${baseId}-opt-${index}`}
                    role="option"
                    aria-selected={isSelected}
                    aria-disabled={option.disabled ? true : undefined}
                    data-option={option.value}
                    data-highlighted={isHighlighted ? "true" : "false"}
                    data-disabled={option.disabled ? "true" : undefined}
                    onPointerMove={() => { if (!option.disabled && highlighted !== option.value) setHighlighted(option.value); }}
                    onClick={() => select(option.value)}
                    className="relative flex h-8 cursor-default select-none items-center gap-2 rounded-lg px-2 text-[13px] text-foreground outline-none data-[disabled=true]:opacity-40 data-[highlighted=true]:bg-muted"
                  >
                    <span aria-hidden="true" className="flex size-5 shrink-0 items-center justify-center">
                      <Marker option={option} kind={kind} avatarSize={20} />
                    </span>
                    <span className="min-w-0 flex-1 truncate">{option.label}</span>
                    {isSelected ? (
                      <Check data-check aria-hidden="true" className="size-3.5 shrink-0 text-foreground" strokeWidth={2.25} />
                    ) : option.shortcut !== undefined ? (
                      <kbd data-shortcut aria-hidden="true" className="shrink-0 font-mono text-[11px] text-muted-foreground">{option.shortcut}</kbd>
                    ) : null}
                  </li>
                );
              })}
            </React.Fragment>
          ))}
        </ul>,
        document.body,
      )}
      {flight && flightOption && createPortal(
        <span
          ref={ghostRef}
          data-fly-ghost
          aria-hidden="true"
          className="pointer-events-none fixed z-[60] flex items-center justify-center will-change-[transform,filter]"
          style={{ left: flight.from.left, top: flight.from.top, width: flight.from.width, height: flight.from.height }}
        >
          <Marker option={flightOption} kind={kind} avatarSize={flight.from.width} />
        </span>,
        document.body,
      )}
    </div>
  );
}

export default StatusDropdownSelect;

