"use client";

import * as React from "react";
import { Circle } from "lucide-react";
import { StatusDropdownSelect } from "@/components/ui/status-dropdown-select";
import type { StatusOption } from "@/components/ui/status-dropdown-select";

type DemoProps = { autoplay?: boolean };
type Field = "status" | "priority" | "assignee";
type Values = { status: string; priority: string; assignee: string };
type Issue = { id: string; title: string; values: Values };
type Step = { at: number; run: () => void };

const CYCLE = 15000;
const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";

const HEADSHOTS = {
  "photo-1629425733761-caae3b5f2e50": "data:image/webp;base64,",
  "photo-1500648767791-00dcc994a43e": "data:image/webp;base64,",
  "photo-1543949806-2c9935e6aa78": "data:image/webp;base64,",
  "photo-1627161683077-e34782c24d81": "data:image/webp;base64,",
} as const;

function Bars({ level, urgent = false }: { level: 0 | 1 | 2 | 3 | 4; urgent?: boolean }) {
  return (
    <span aria-hidden="true" className="flex size-3.5 items-end justify-center gap-px">
      {[1, 2, 3, 4].map((bar) => (
        <span
          key={bar}
          className={`w-[2px] rounded-[1px] ${bar <= level ? (urgent ? "bg-destructive" : "bg-foreground") : "bg-muted-foreground/30"}`}
          style={{ height: `${4 + (bar - 1) * 3}px` }}
        />
      ))}
    </span>
  );
}

const STATUS: StatusOption[] = [
  { value: "backlog", label: "Backlog", color: "muted", group: "Planned", shortcut: "1" },
  { value: "todo", label: "Todo", color: "chart-4", group: "Planned", shortcut: "2" },
  { value: "in_progress", label: "In progress", color: "chart-1", group: "Started", shortcut: "3" },
  { value: "in_review", label: "In review", color: "chart-3", group: "Started", shortcut: "4" },
  { value: "done", label: "Done", color: "chart-2", group: "Closed", shortcut: "5" },
  { value: "canceled", label: "Canceled", color: "destructive", group: "Closed", shortcut: "6" },
];

const PRIORITY: StatusOption[] = [
  { value: "none", label: "No priority", color: "muted", icon: <Bars level={0} />, shortcut: "0" },
  { value: "low", label: "Low", icon: <Bars level={1} />, shortcut: "1" },
  { value: "medium", label: "Medium", icon: <Bars level={2} />, shortcut: "2" },
  { value: "high", label: "High", icon: <Bars level={3} />, shortcut: "3" },
  { value: "urgent", label: "Urgent", color: "destructive", icon: <Bars level={4} urgent />, shortcut: "4" },
];

const ASSIGNEE: StatusOption[] = [
  { value: "unassigned", label: "Unassigned", color: "muted" },
  { value: "jordan", label: "Jordan Lee", avatarUrl: HEADSHOTS["photo-1629425733761-caae3b5f2e50"] },
  { value: "mina", label: "Mina Park", avatarUrl: HEADSHOTS["photo-1500648767791-00dcc994a43e"] },
  { value: "theo", label: "Theo Alvarez", avatarUrl: HEADSHOTS["photo-1543949806-2c9935e6aa78"] },
  { value: "sora", label: "Sora Kim", avatarUrl: HEADSHOTS["photo-1627161683077-e34782c24d81"] },
];

const ISSUES: Issue[] = [
  { id: "ALD-248", title: "Fix checkout latency on mobile", values: { status: "todo", priority: "none", assignee: "unassigned" } },
  { id: "ALD-251", title: "Add passkey sign-in to the web app", values: { status: "backlog", priority: "none", assignee: "unassigned" } },
];

const FIELDS: { key: Field; label: string; options: StatusOption[]; kind: "dot" | "icon" | "avatar" }[] = [
  { key: "status", label: "Status", options: STATUS, kind: "dot" },
  { key: "priority", label: "Priority", options: PRIORITY, kind: "icon" },
  { key: "assignee", label: "Assignee", options: ASSIGNEE, kind: "avatar" },
];

export default function Demo({ autoplay = true }: DemoProps) {
  const params = React.useMemo(() => new URLSearchParams(typeof window === "undefined" ? "" : window.location.search), []);
  const controlled = params.get("controlled") === "1";
  const uncontrolled = params.get("uncontrolled") === "1";
  const fly = params.get("fly") !== "0";
  const size = params.get("size") === "sm" ? "sm" : "md";
  const align = params.get("align") === "end" ? "end" : "start";
  const first = ISSUES[0]!;

  const [issueIndex, setIssueIndex] = React.useState(0);
  const [values, setValues] = React.useState(first.values);
  const [openField, setOpenField] = React.useState(null as Field | null);
  const [requests, setRequests] = React.useState([] as string[]);
  const [motion, setMotion] = React.useState({ ready: false, reduced: true });
  const [paused, setPaused] = React.useState(false);
  const [run, setRun] = React.useState(0);
  const rootRef = React.useRef(null as HTMLElement | null);
  const cardRef = React.useRef(null as HTMLDivElement | null);
  const titleRef = React.useRef(null as HTMLDivElement | null);
  const statusRef = React.useRef(null as HTMLDivElement | null);
  const scripted = autoplay && !controlled && !uncontrolled && !paused;
  const issue = ISSUES[issueIndex] ?? first;

  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setMotion({ ready: true, reduced: media.matches });
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  React.useEffect(() => {
    if (!motion.ready || motion.reduced) return;
    const card = cardRef.current;
    if (card && typeof card.animate === "function") {
      card.animate([{ opacity: 0, transform: "translateY(12px)" }, { opacity: 1, transform: "translateY(0)" }], { duration: 360, easing: EASE });
    }
  }, [motion.ready, motion.reduced]);

  const pressKey = React.useCallback((key: string) => {
    const trigger = statusRef.current?.querySelector("[data-trigger]");
    const id = trigger?.getAttribute("aria-controls");
    const listbox = id ? document.getElementById(id) : null;
    listbox?.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  }, []);

  const switchIssue = React.useCallback((index: number) => {
    const next = ISSUES[index];
    if (!next) return;
    setIssueIndex(index);
    setValues(next.values);
    setOpenField(null);
    const title = titleRef.current;
    if (title && typeof title.animate === "function" && !motion.reduced) {
      title.animate([{ opacity: 0, transform: "translateY(4px)" }, { opacity: 1, transform: "translateY(0)" }], { duration: 260, easing: EASE });
    }
  }, [motion.reduced]);

  React.useEffect(() => {
    if (!motion.ready || motion.reduced || !scripted) return;
    const root = rootRef.current;
    let count = 0;
    if (root) { root.dataset.tourStarted = performance.now().toFixed(1); root.dataset.tourStep = "0"; }
    const pick = (field: Field, value: string) => { setValues((current) => ({ ...current, [field]: value })); setOpenField(null); };
    const script: Step[] = [
      { at: 500, run: () => setOpenField("status") },
      { at: 1500, run: () => pick("status", "in_progress") },
      { at: 3200, run: () => setOpenField("priority") },
      { at: 4000, run: () => pick("priority", "high") },
      { at: 4700, run: () => setOpenField("assignee") },
      { at: 5400, run: () => pick("assignee", "mina") },
      { at: 7200, run: () => switchIssue(1) },
      { at: 7900, run: () => setOpenField("status") },
      { at: 8500, run: () => pressKey("ArrowDown") },
      { at: 8900, run: () => pressKey("ArrowDown") },
      { at: 9500, run: () => pressKey("Enter") },
      { at: 10800, run: () => setOpenField("priority") },
      { at: 11600, run: () => pick("priority", "urgent") },
      { at: 12300, run: () => setOpenField("assignee") },
      { at: 13000, run: () => pick("assignee", "theo") },
      { at: 14600, run: () => switchIssue(0) },
    ];
    const timers = script.map((step) => window.setTimeout(() => {
      step.run();
      count += 1;
      if (root) { root.dataset.tourStep = String(count); root.dataset.tourLastAt = performance.now().toFixed(1); }
    }, step.at));
    timers.push(window.setTimeout(() => setRun((previous) => previous + 1), CYCLE));
    return () => timers.forEach((timer) => window.clearTimeout(timer));
  }, [motion.ready, motion.reduced, scripted, run, pressKey, switchIssue]);

  const takeOver = (event: React.SyntheticEvent) => { if (scripted && event.nativeEvent.isTrusted) setPaused(true); };
  const note = (entry: string) => setRequests((previous) => [...previous, entry]);

  return (
    <main
      ref={rootRef}
      data-demo="status-dropdown-select"
      data-issue={issue.id}
      className="relative flex w-full items-center justify-center bg-background p-4 text-foreground"
      style={{ height: "min(100svh, 760px)" }}
      onPointerDownCapture={takeOver}
      onKeyDownCapture={takeOver}
    >
      <div ref={cardRef} data-issue-card className="w-full max-w-[720px] rounded-2xl bg-card p-3 text-card-foreground shadow-sm shadow-foreground/5 ring-1 ring-border sm:p-3.5">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:gap-4">
          <div ref={titleRef} className="flex min-w-0 flex-1 items-center gap-2.5">
            <span className="flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground"><Circle className="size-4" strokeWidth={1.75} aria-hidden="true" /></span>
            <span data-issue-id className="shrink-0 font-mono text-xs text-muted-foreground">{issue.id}</span>
            <span data-issue-title className="min-w-0 truncate text-sm font-medium">{issue.title}</span>
          </div>
          <div className="grid grid-cols-[auto_1fr] items-center gap-x-3 gap-y-2 sm:flex sm:shrink-0 sm:items-center sm:gap-2">
            {FIELDS.map((field) => (
              <React.Fragment key={field.key}>
                <span className="text-xs text-muted-foreground sm:sr-only">{field.label}</span>
                <StatusDropdownSelect
                  ref={field.key === "status" ? statusRef : undefined}
                  data-field={field.key}
                  className="justify-self-start"
                  options={field.options}
                  kind={field.kind}
                  label={field.label}
                  size={size}
                  fly={fly}
                  align={align}
                  menuWidth={field.kind === "avatar" ? 232 : 224}
                  {...(uncontrolled
                    ? { defaultValue: issue.values[field.key] }
                    : controlled
                      ? { value: first.values[field.key], onValueChange: (next: string) => note(`${field.key}:${next}`) }
                      : { value: values[field.key], onValueChange: (next: string) => setValues((current) => ({ ...current, [field.key]: next })) })}
                  {...(uncontrolled || controlled
                    ? {}
                    : { open: openField === field.key, onOpenChange: (next: boolean) => setOpenField((current) => (next ? field.key : current === field.key ? null : current)) })}
                />
              </React.Fragment>
            ))}
          </div>
        </div>
      </div>
      {controlled && <output data-requests className="sr-only">{requests.join(" ")}</output>}
    </main>
  );
}
